<template>
 <section class="ledger-panel delivery-panel" aria-label="续费与投放衔接">
  <div class="ledger-section-heading"><div><h2>续费与投放衔接</h2><p>检查新旧档期，再明确更新关联广告。</p></div></div>
  <div class="delivery-body"><p class="ledger-small">{{ order.delivery_covered ? '关联广告已覆盖本订单位置和档期。' : '本订单尚未由关联广告完整覆盖。' }} 保存订单不会自动调整投放。</p><a-button :loading="loading" :disabled="busy || !!order.cancelled" @click="check">{{ plan ? '重新检查投放安排' : '检查投放安排' }}</a-button>
   <p v-if="error" class="ledger-error" role="alert">{{ error }}</p>
   <div v-if="plan" class="delivery-plan"><b>{{ plan.ad_name || '尚未关联广告' }}</b><div class="delivery-schedules"><article><span>当前投放</span><b>{{ plan.current ? SLOT[plan.current.slot] : '未关联' }}</b><small v-if="plan.current">{{ plan.current.start_date }} → {{ plan.current.end_date }}</small></article><article><span>更新后投放</span><b>{{ SLOT[plan.proposed.slot] }}</b><small>{{ plan.proposed.start_date }} → {{ plan.proposed.end_date }}</small></article></div><p class="ledger-small">到期日当天撤下；连续续费会保留原开始日，延长到新到期日。</p><p v-for="reason in plan.reasons" :key="reason" class="ledger-conflict">{{ reason }}</p><p v-for="warning in plan.warnings" :key="warning" class="delivery-warning">{{ warning }}</p><div v-for="p in plan.availability.placements" :key="p.slot" class="delivery-capacity"><b>{{ p.label }}</b><span>{{ p.capacity==null ? '不限名额' : p.available ? '档期内至少余 '+p.remaining+' 位' : '有时段已满' }}</span><small v-if="p.conflict">{{ p.conflict.start }} 至 {{ p.conflict.end }}（不含结束日）：{{ p.conflict.ads.map(ad=>ad.name).join('、') }}</small></div><p v-if="plan.up_to_date" class="delivery-success">已覆盖本订单，无需重复更新。</p><template v-if="plan.can_apply"><p class="ledger-small">确认后更新广告 #{{ plan.ad_id }} 的位置和档期，素材、链接与收款记录保持原样。</p><a-button type="primary" :loading="busy" :disabled="loading" @click="apply">确认更新关联广告</a-button></template></div>
   <details v-if="order.deliveries?.length" class="delivery-history"><summary>投放更新记录 · {{ order.deliveries.length }}</summary><article v-for="row in order.deliveries" :key="row.id"><b>{{ SLOT[row.after_schedule.slot] }} · {{ row.after_schedule.start_date }} → {{ row.after_schedule.end_date }}</b><small>原档期 {{ row.before_schedule.start_date }} → {{ row.before_schedule.end_date }}</small><small>{{ new Date(row.applied_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}) }} 北京时间</small></article></details>
  </div>
 </section>
</template>
<script setup>
import { ref,watch } from 'vue';
import { Message } from '@arco-design/web-vue';
import { api,SLOT } from '../api';
import { newRequestKey } from '../ad-order';
const props=defineProps({order:{type:Object,required:true},beforePreview:Function});const emit=defineEmits(['updated']);
const plan=ref(null),loading=ref(false),busy=ref(false),error=ref('');let serial=0,key='';
async function check(){if(props.beforePreview && !props.beforePreview())return;const current=++serial;loading.value=true;error.value='';plan.value=null;try{const result=await api(`/api/ad-orders/${props.order.id}/delivery-preview`);if(current===serial){plan.value=result;key=newRequestKey();}}catch(err){if(current===serial)error.value=err.message;}finally{if(current===serial)loading.value=false;}}
async function apply(){if(busy.value || !plan.value?.can_apply || (props.beforePreview && !props.beforePreview()))return;const orderId=props.order.id;busy.value=true;error.value='';try{const row=await api(`/api/ad-orders/${orderId}/delivery`,{method:'POST',body:JSON.stringify({preview_token:plan.value.preview_token,request_key:key})});if(props.order.id===orderId){emit('updated',row);plan.value=null;Message.success('关联广告已更新，投放记录已保存');}}catch(err){if(props.order.id===orderId)error.value=err.message;}finally{busy.value=false;}}
watch(()=>[props.order.id,props.order.version],()=>{serial++;plan.value=null;error.value='';loading.value=false;});
</script>
<style>
.delivery-body{padding:0 24px 24px;min-width:0}.delivery-body>.ledger-small{margin-top:0;line-height:1.9}.delivery-plan{border-top:1px solid #e9eeef;margin-top:18px;padding-top:18px;font-size:12px;color:#3f5966;overflow-wrap:anywhere}.delivery-schedules{display:grid;grid-template-columns:1fr;gap:8px;margin-top:14px}.delivery-schedules article{padding:12px;background:#f7f9f9;border-radius:7px;display:flex;flex-direction:column;gap:6px}.delivery-schedules span,.delivery-schedules small{font-size:11px;color:#8798a1}.delivery-schedules b{font-weight:500}.delivery-warning{font-size:11px;line-height:1.8;color:#ac874b}.delivery-capacity{padding:12px 0;border-top:1px solid #edf0f1;display:flex;gap:8px;flex-wrap:wrap;justify-content:space-between;font-size:11px}.delivery-capacity b{font-weight:500}.delivery-capacity span{color:#87999e}.delivery-capacity small{width:100%;line-height:1.8;color:#af8545}.delivery-success{color:#688d4c;font-size:12px;line-height:1.8}.delivery-history{margin-top:20px;color:#85969d;font-size:11px}.delivery-history summary{cursor:pointer}.delivery-history article{display:flex;flex-direction:column;gap:6px;margin-top:12px;line-height:1.7}.delivery-history b{font-weight:500;color:#506a76}@media(max-width:600px){.delivery-body{padding:0 16px 20px}}
</style>
